    @Mock
    private UserRepository userRepository;

    @Mock
    private PasswordEncoder passwordEncoder;

    @Mock
    private AuthenticationManager authenticationManager;

    @Mock
    private JwtUtils jwtUtils;

    @InjectMocks
    private AuthService authService;

    @BeforeEach
    public void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void testRegister_WhenEmailExists_ShouldThrowException() {
        RegisterRequest registerRequest = new RegisterRequest("existing@example.com", "user123", "password");

        when(userRepository.existsByEmail(any(String.class))).thenReturn(true);

        assertThrows(IllegalArgumentException.class, () -> authService.register(registerRequest));
    }

    @Test
    public void testRegister_WhenUsernameExists_ShouldThrowException() {
        RegisterRequest registerRequest = new RegisterRequest("new@example.com", "existingUser", "password");

        when(userRepository.existsByUsername(any(String.class))).thenReturn(true);

        assertThrows(IllegalArgumentException.class, () -> authService.register(registerRequest));
    }

    @Test
    public void testRegister_WhenEmailAndUsernameAreUnique_ShouldSucceed() {
        RegisterRequest registerRequest = new RegisterRequest("new@example.com", "uniqueUser", "password");
        User user = User.builder()
                .username("uniqueUser")
                .email("new@example.com")
                .password(passwordEncoder.encode("password"))
                .build();

        when(userRepository.existsByEmail(any(String.class))).thenReturn(false);
        when(userRepository.existsByUsername(any(String.class))).thenReturn(false);
        when(userRepository.save(any(User.class))).thenReturn(user);
        when(jwtUtils.generateToken(anyString())).thenReturn("token");

        AuthResponse authResponse = authService.register(registerRequest);

        assertEquals("token", authResponse.getToken());
        assertEquals("uniqueUser", authResponse.getUsername());
        assertEquals("new@example.com", authResponse.getEmail());

        verify(userRepository, times(1)).save(user);
    }

    @Test
    public void testLogin_WhenUserExists_ShouldSucceed() {
        LoginRequest loginRequest = new LoginRequest("existingUser", "password");
        User user = User.builder()
                .username("existingUser")
                .email("existing@example.com")
                .password(passwordEncoder.encode("password"))
                .build();

        when(authenticationManager.authenticate(any(UsernamePasswordAuthenticationToken.class))).thenReturn(null);
        when(userRepository.findByUsername(anyString())).thenReturn(Optional.of(user));
        when(jwtUtils.generateToken(anyString())).thenReturn("token");

        AuthResponse authResponse = authService.login(loginRequest);

        assertEquals("token", authResponse.getToken());
        assertEquals("existingUser", authResponse.getUsername());
        assertEquals("existing@example.com", authResponse.getEmail());

        verify(authenticationManager, times(1)).authenticate(any(UsernamePasswordAuthenticationToken.class));
    }

    @Test
    public void testLogin_WhenUserDoesNotExist_ShouldThrowException() {
        LoginRequest loginRequest = new LoginRequest("nonExistentUser", "password");

        when(userRepository.findByUsername(anyString())).thenReturn(Optional.empty());

        assertThrows(IllegalArgumentException.class, () -> authService.login(loginRequest));
    }
}
```

